class Solution(object):
    def maxTurbulenceSize(self, A):
        """
        :type A: List[int]
        :rtype: int
        """
        if not A:
            return 0

        n = len(A)
        if n == 1:
            return 1

        max_len = 1
        up = 1  # 以 i 結尾的上升子陣列長度
        down = 1  # 以 i 結尾的下降子陣列長度

        for i in range(1, n):
            try:
                if A[i] > A[i-1]:
                    up = down + 1
                    down = 1
                elif A[i] < A[i-1]:
                    down = up + 1
                    up = 1
                else:
                    up = down = 1
                max_len = max(max_len, up, down)
            except IndexError:
                # 捕捉極端邊界情況
                pass

        return max_len
